CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), feishu_open_id text NOT NULL UNIQUE, display_name text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY(user_id, role_id));
CREATE TABLE api_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, fingerprint char(64) NOT NULL UNIQUE, secret_hash text NOT NULL, role_id uuid NOT NULL REFERENCES roles(id), expires_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE web_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_hash char(64) NOT NULL UNIQUE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_hash char(64) NOT NULL, expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_states (state_hash char(64) PRIMARY KEY, return_path text NOT NULL DEFAULT '/', expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE clusters (id uuid PRIMARY KEY, name text NOT NULL UNIQUE, api_server text NOT NULL, encrypted_kubeconfig bytea NOT NULL, credential_version bigint NOT NULL DEFAULT 1, enabled boolean NOT NULL DEFAULT true, last_check_status text NOT NULL DEFAULT 'unknown', last_checked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_environments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE, name text NOT NULL CHECK(name IN ('development','test','production')), cluster_id uuid NOT NULL REFERENCES clusters(id), namespace text NOT NULL, deployment text NOT NULL, container text NOT NULL, image_prefix text NOT NULL, approval_required boolean NOT NULL, rollout_timeout_seconds integer NOT NULL DEFAULT 600, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(application_id,name));
CREATE TABLE app_permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, application_id uuid REFERENCES applications(id) ON DELETE CASCADE, action text NOT NULL CHECK(action IN ('view','deploy','rollback','approve','admin')), UNIQUE NULLS NOT DISTINCT(role_id,application_id,action));
CREATE TABLE operations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('deploy','rollback')), status text NOT NULL, application_id uuid NOT NULL REFERENCES applications(id), environment_id uuid NOT NULL REFERENCES app_environments(id), requester_id uuid NOT NULL REFERENCES users(id), image text NOT NULL DEFAULT '', revision bigint NOT NULL DEFAULT 0, idempotency_key text NOT NULL UNIQUE, error_code text NOT NULL DEFAULT '', error_message text NOT NULL DEFAULT '', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), claimed_by text, claimed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX operations_queue_idx ON operations(status,next_attempt_at,created_at);
CREATE TABLE approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_id uuid NOT NULL REFERENCES operations(id) ON DELETE CASCADE, approver_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL CHECK(decision IN ('approved','rejected')), comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(operation_id));
CREATE TABLE audit_events (id bigserial PRIMARY KEY, actor_user_id uuid REFERENCES users(id), actor_token_id uuid REFERENCES api_tokens(id), action text NOT NULL, resource_type text NOT NULL, resource_id uuid, request_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_filter_idx ON audit_events(resource_type,resource_id,created_at DESC);
CREATE TABLE inbox_events (id text PRIMARY KEY, kind text NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic text NOT NULL, destination text NOT NULL, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz, last_error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending_idx ON outbox_messages(next_attempt_at) WHERE sent_at IS NULL;
CREATE TABLE operation_events (id bigserial PRIMARY KEY, operation_id uuid REFERENCES operations(id) ON DELETE CASCADE, application_id uuid REFERENCES applications(id), kind text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX operation_events_cursor_idx ON operation_events(id,created_at);
CREATE TABLE target_leases (environment_id uuid PRIMARY KEY REFERENCES app_environments(id) ON DELETE CASCADE, operation_id uuid NOT NULL REFERENCES operations(id) ON DELETE CASCADE, owner text NOT NULL, fencing_token bigint NOT NULL, expires_at timestamptz NOT NULL, heartbeat_at timestamptz NOT NULL DEFAULT now());
INSERT INTO roles(name,description) VALUES ('admin','Full administration'),('operator','Application deploy and rollback'),('approver','Production approval') ON CONFLICT DO NOTHING;
